def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """

    def switch_case(ch):
        """Swap the case of a character."""
        if 'A' <= ch <= 'Z':
            return ch.lower()
        elif 'a' <= ch <= 'z':
            return ch.upper()
        else:
            return ch

    def vowel_change(ch):
        """Replace vowels with the letter 2 positions ahead in the alphabet."""
        vowels = set("aeiouAEIOU")
        if ch in vowels:
            # Ensure we wrap around if needed (though problem assumes only letters)
            offset = ord(ch) + 2
            if 'a' <= ch <= 'y':
                return chr(offset)
            elif 'A' <= ch <= 'Y':
                return chr(offset)
            else:
                # Fallback for 'z' or 'Z' if wrapping is desired; 
                # based on examples, simple shift is used without explicit wrap logic shown.
                return ch
        return ch

    # First, swap the case of all characters
    swapped_message = "".join(map(switch_case, message))

    # Then, replace vowels with the letter 2 positions ahead
    encoded_message = "".join(map(vowel_change, swapped_message))

    return encoded_message
