def split_words(txt):
    """
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25

    Examples:
        split_words("Hello world!") ➞ ["Hello", "world!"]
        split_words("Hello,world!") ➞ ["Hello", "world!"]
        split_words("abcdef") == 3
    """
    # Define whitespace characters once for clarity
    whitespace_chars = {' ', '\n', '\r', '\t'}

    # Check if the text contains any whitespace
    if any(ch in whitespace_chars for ch in txt):
        return txt.split()

    # Check if the text contains a comma
    if ',' in txt:
        return txt.split(',')

    # Count lowercase letters with an odd position in the alphabet (a=0, b=1, ...)
    count = 0
    for ch in txt:
        if ch.islower():
            # Calculate position: ord('a') = 0, ord('b') = 1, etc.
            position = ord(ch) - ord('a')
            if position % 2 == 1:
                count += 1

    return count
